import csv,re,json
# parse S3 2504
names=set()
for i,l in enumerate(open('dragen_igsr_30x.tsv')):
    if i==0: continue
    if l.strip(): names.add(l.split('\\t')[0])
rows=[]
for exp in json.load(open('encode_mont_atac_exp_fields.json'))['@graph']:
    disp=exp['biosample_summary'].split()[-1]
    cand=[disp]
    if re.fullmatch(r'GM\\d+',disp): cand.append('NA'+disp[2:])
    if any(c in names for c in cand): rows.append(disp)
print(len(rows), rows[:10])
PY"
